import subprocess,time,numpy as np
from PIL import Image
def mon(c): subprocess.run(['python3','qmon.py',c],stdout=subprocess.DEVNULL)
mon('system_reset')
for i in range(60):
    mon('screendump /app/p.ppm')
    try:
        im=Image.open('p.ppm'); a=np.asarray(im.convert('RGB')); nz=int((a.sum(2)>25).sum())
    except: continue
    if im.size==(720,400) and 100<nz<7000:
        im.save(f'txt_{i}.png'); print('saved',i,nz)
"

