import socket,sys,time
text=sys.argv[1]
enter = len(sys.argv)>2 and sys.argv[2]=='1'
m={' ':'spc','\\':'backslash','/':'slash','.':'dot',':':'shift-semicolon',
   '-':'minus','_':'shift-minus','=':'equal',';':'semicolon',',':'comma'}
seq=[]
for c in text:
    if c in m: seq.append(m[c])
    elif c.isalnum(): seq.append(c.lower())
    else: seq.append(c)
if enter: seq.append('ret')
s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
s.connect('/tmp/qemu-monitor.sock')
time.sleep(0.1); s.settimeout(0.3)
try:
  while s.recv(4096): pass
except: pass
for k in seq:
    s.sendall((f'sendkey {k}\n').encode()); time.sleep(0.06)
    try: s.recv(4096)
    except: pass
print('typed',text)

