# Standalone nginx config: web interface for VNC on port 80.
# Run with: nginx -c /app/nginx.conf
worker_processes 1;
pid /tmp/nginx-win311.pid;
error_log /tmp/nginx-error.log;
events { worker_connections 256; }
http {
    access_log /tmp/nginx-access.log;
    client_body_temp_path /tmp/nginx-cbt;
    proxy_temp_path /tmp/nginx-pt;
    fastcgi_temp_path /tmp/nginx-ft;
    uwsgi_temp_path /tmp/nginx-ut;
    scgi_temp_path /tmp/nginx-st;
    types_hash_max_size 2048;
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    map $http_upgrade $connection_upgrade { default upgrade; '' close; }

    server {
        listen 80 default_server;
        listen [::]:80 default_server;

        # noVNC web client + websockify (static + websocket) live behind
        # websockify on 6080; proxy everything, upgrading websockets.
        location / {
            proxy_pass http://127.0.0.1:6080;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection $connection_upgrade;
            proxy_set_header Host $host;
            proxy_read_timeout 61s;
        }
    }
}

